#include <iostream>
#include <cmath>
#include <iomanip>
#include <limits>

/**
 * @brief Calculates the perpendicular distance from a point to a plane.
 * 
 * The formula used is: d = |Ax₀ + By₀ + Cz₀ + D| / sqrt(A² + B² + C²)
 * where the plane equation is Ax + By + Cz + D = 0.
 * 
 * @param a Coefficient of x
 * @param b Coefficient of y
 * @param c Coefficient of z
 * @param d Coefficient of the plane constant
 * @param x Coordinate of the point
 * @param y Coordinate of the point
 * @param z Coordinate of the point
 * @return double The calculated distance
 */
double calculateDistance(double a, double b, double c, double d, 
                         double x, double y, double z) {
    // Calculate the numerator: |Ax + By + Cz + D|
    double numerator = std::abs(a * x + b * y + c * z + d);

    // Calculate the denominator: sqrt(A² + B² + C²)
    double denominator = std::sqrt(a * a + b * b + c * c);

    // Handle edge case where the plane normal vector is zero (invalid plane)
    if (denominator == 0.0) {
        return std::numeric_limits<double>::infinity();
    }

    return numerator / denominator;
}

int main() {
    std::cout << std::fixed << std::setprecision(2); // Set output precision to 2 decimal places

    double ax, by, cz, d;
    double px, py, pz;

    std::cout << "=== Distance from Point to Plane Calculator ===\n\n";

    // Input coefficients for the plane (Ax + By + Cz + D = 0)
    std::cout << "Enter plane coefficients (A, B, C, D): ";
    while (!(std::cin >> ax >> by >> cz >> d)) {
        std::cout << "Invalid input. Please enter four valid numbers separated by spaces.\n";
        std::cin.clear(); // Clear error flags
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n'); // Discard invalid input
        std::cout << "Enter plane coefficients (A, B, C, D): ";
    }

    // Request at least one coefficient to be non-zero to define a valid plane
    double norm = std::sqrt(ax*ax + by*by + cz*cz);
    if (norm == 0.0) {
        std::cout << "Error: At least one of the plane coefficients (A, B, or C) must be non-zero.\n";
        return 1;
    }

    // Input point coordinates (x, y, z)
    std::cout << "\nEnter point coordinates (x, y, z): ";
    while (!(std::cin >> px >> py >> pz)) {
        std::cout << "Invalid input. Please enter three valid numbers separated by spaces.\n";
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        std::cout << "Enter point coordinates (x, y, z): ";
    }

    // Perform calculation
    double distance = calculateDistance(ax, by, cz, d, px, py, pz);

    // Output results
    std::cout << "\n--- Results ---\n";
    std::cout << "Plane Equation: ";
    std::cout << ax << "x + ";
    std::cout << by << "y + ";
    std::cout << cz << "z + ";
    std::cout << d << " = 0\n";

    std::cout << "Point Coordinates: (";
    std::cout << px << ", ";
    std::cout << py << ", ";
    std::cout << pz << ")\n";

    // Handle potential infinity/NaN scenarios for display
    if (std::isinf(distance)) {
        std::cout << "Distance: Undefined (Invalid Plane)\n";
    } else if (std::isnan(distance)) {
        std::cout << "Distance: NaN (Invalid Calculation)\n";
    } else {
        std::cout << "Distance from point to plane: " << distance << " units\n";
    }

    return 0;
}
